import { SemverSchema } from '../version.js';

/** Compares MAJOR.MINOR.PATCH versions: negative if a < b, 0 if equal, positive if a > b. */
export function compareSemver(a: string, b: string): number {
  const parse = (version: string): number[] => {
    if (!SemverSchema.safeParse(version).success)
      throw new TypeError(`Invalid semantic version: ${version}`);
    return version.split('.').map(Number);
  };
  const left = parse(a);
  const right = parse(b);
  for (let i = 0; i < 3; i += 1) {
    const diff = (left[i] ?? 0) - (right[i] ?? 0);
    if (diff !== 0) return diff;
  }
  return 0;
}

src/migrations/types.ts.source:
/** Untyped document as stored for an older schema version. Migrations must not assume more. */
export type RawDocument = Record<string, unknown>;

export interface Migration {
  readonly from: string;
  readonly to: string;
  readonly description: string;
  /** Pure: receives a private deep copy and returns the migrated document (may mutate the copy). */
  readonly up: (doc: RawDocument) => RawDocument;
}

export type MigrationErrorCode =
  | 'SCHEMA_VERSION_MISSING'
  | 'SCHEMA_VERSION_UNSUPPORTED'
  | 'MIGRATION_FAILED'
  | 'MIGRATION_REGISTRY_INVALID';

export class MigrationError extends Error {
  override readonly name = 'MigrationError';

  constructor(
    readonly code: MigrationErrorCode,
    message: string,
    readonly version?: string,
    options?: ErrorOptions,
  ) {
    super(message, options);
  }
}

