/** Stable machine codes for script validation issues. Never rename; add new ones instead. */
export const VALIDATION_CODES = [
  // Structural (zod) and format
  'SCHEMA_INVALID',
  'SCHEMA_VERSION_MISSING',
  'SCHEMA_VERSION_UNSUPPORTED',
  'MIGRATION_FAILED',
  'DOCUMENT_TOO_LARGE',
  'NODE_DEPTH_EXCEEDED',
  'NODE_COUNT_EXCEEDED',
  // Identity
  'DUPLICATE_ID',
  'SCENARIO_INVALID',
  'SCENARIO_SENSITIVE',
  // References
  'PAGE_REF_BROKEN',
  'DATASOURCE_REF_BROKEN',
  'DATASOURCE_FIELD_UNKNOWN',
  'RULE_REF_BROKEN',
  'SUBFLOW_REF_BROKEN',
  'TIMER_REF_BROKEN',
  'NODE_REF_BROKEN',
  'VARIABLE_UNDEFINED',
  'COMPONENT_TYPE_UNKNOWN',
  // Flow graph
  'FLOW_START_MISSING',
  'FLOW_EDGE_BROKEN',
  'FLOW_CYCLE',
  'SUBFLOW_CYCLE',
  'FLOW_NODE_UNREACHABLE',
  'FLOW_DEAD_END',
  'FLOW_DATASOURCE_NO_ERROR_EDGE',
  'PAGE_UNREACHABLE',
  // Variables and data classification
  'VARIABLE_READONLY',
  'VARIABLE_TYPE_MISMATCH',
  'VARIABLE_ENUM_VALUES_MISSING',
  'VARIABLE_PCI_PERSISTED',
  'VARIABLE_CLASSIFICATION_MISMATCH',
  'SENSITIVE_DATA_EXPOSED',
  'CONSENT_PRESELECTED',
  // Bindings and i18n
  'BINDING_DUPLICATE_PROP',
  'I18N_DEFAULT_LOCALE_MISSING',
  'I18N_KEY_MISSING',
  'I18N_TRANSLATION_MISSING',
  'I18N_LITERAL_TEXT',
] as const;

export type ValidationCode = (typeof VALIDATION_CODES)[number];
export type Severity = 'error' | 'warning' | 'info';

export interface ValidationIssue {
  readonly severity: Severity;
  /** JSON Pointer (RFC 6901) into the document, e.g. `/pages/0/layout/children/2`. */
  readonly path: string;
  readonly code: ValidationCode;
  /** i18n key in `@verbis/i18n` (`script.validation.*`). */
  readonly messageKey: string;
  /** Interpolation parameters for the message. Never contains variable values. */
  readonly params?: Readonly<Record<string, string | number>>;
}

/** `FLOW_CYCLE` → `script.validation.flowCycle`. */
export function messageKeyFor(code: ValidationCode): string {
  const camel = code.toLowerCase().replace(/_([a-z0-9])/g, (_, char: string) => char.toUpperCase());
  return `script.validation.${camel}`;
}

export function createIssue(
  severity: Severity,
  code: ValidationCode,
  path: string,
  params?: Readonly<Record<string, string | number>>,
): ValidationIssue {
  return params === undefined
    ? { severity, path, code, messageKey: messageKeyFor(code) }
    : { severity, path, code, messageKey: messageKeyFor(code), params };
}

export function hasErrors(issues: readonly ValidationIssue[]): boolean {
  return issues.some((issue) => issue.severity === 'error');
}

src/validation/references.ts.source:
/**
 * Conservative reference scanner for expression source text. It does not parse or evaluate
 * (ADR-0007); it only finds `vars.<key>` and `ds.<id>[.<field>]` member chains outside string
 * literals so the validator can check them. The step-13 parser will supply AST-based references.
 */
export interface ExpressionReferences {
  readonly variables: readonly string[];
  readonly dataSources: readonly { readonly id: string; readonly field?: string }[];
}

const IDENT_START = /[A-Za-z_$]/;
const IDENT_PART = /[A-Za-z0-9_$]/;

function stripStrings(source: string): string {
  let out = '';
  let quote: string | null = null;
  for (let i = 0; i < source.length; i += 1) {
    const char = source.charAt(i);
    if (quote !== null) {
      if (char === '\\') i += 1;
      else if (char === quote) {
        quote = null;
        out += ' ';
      }
      continue;
    }
    if (char === '"' || char === "'") {
      quote = char;
      out += ' ';
      continue;
    }
    out += char;
  }
  return out;
}

/** Splits source into member chains like `["vars","customer","name"]`. */
function memberChains(source: string): string[][] {
  const text = stripStrings(source);
  const chains: string[][] = [];
  let i = 0;
  while (i < text.length) {
    const char = text.charAt(i);
    // Skip number literals so `1.5` is not read as a chain; skip `.x` continuing a non-identifier.
    if (/[0-9]/.test(char)) {
      while (i < text.length && /[0-9.eE]/.test(text.charAt(i))) i += 1;
      continue;
    }
    if (!IDENT_START.test(char) || (i > 0 && text.charAt(i - 1) === '.')) {
      i += 1;
      continue;
    }
    const chain: string[] = [];
    let segment = '';
    while (i < text.length) {
      const current = text.charAt(i);
      if (IDENT_PART.test(current)) {
        segment += current;
        i += 1;
      } else if (current === '.' && segment !== '' && IDENT_START.test(text.charAt(i + 1))) {
        chain.push(segment);
        segment = '';
        i += 1;
      } else break;
    }
    if (segment !== '') chain.push(segment);
    chains.push(chain);
  }
  return chains;
}

export function scanExpression(source: string): ExpressionReferences {
  const variables = new Set<string>();
  const dataSources = new Map<string, { id: string; field?: string }>();
  for (const [root, first, second] of memberChains(source)) {
    if (first === undefined) continue;
    if (root === 'vars') variables.add(first);
    if (root === 'ds') {
      const ref = second === undefined ? { id: first } : { id: first, field: second };
      dataSources.set(`${first}.${second ?? ''}`, ref);
    }
  }
  return { variables: [...variables], dataSources: [...dataSources.values()] };
}

/** Scans a rule fact path (`vars.segment`, `ds.lookup.balance`). */
export function scanFactPath(fact: string): ExpressionReferences {
  return scanExpression(fact);
}

