import { z } from 'zod';

import { IdentifierSchema } from '../ids.js';

import { ValueSchema } from './primitives.js';

/** Restricted JSONPath into the mapped response: `$.data.items[0].name`. */
export const JsonPathSchema = z
  .string()
  .max(256)
  .regex(/^\$(\.[A-Za-z_][A-Za-z0-9_]*|\[\d+\])*$/, 'Expected a JSONPath like "$.data.fullName"');

export const DataSourceOutputSchema = z.strictObject({
  path: JsonPathSchema,
  /** Optionally copy the field into a variable after each successful call. */
  variable: IdentifierSchema.optional(),
});

/**
 * Reference to a tenant DataSource (SCRIPT_MODEL §3). The protocol, endpoint and secrets live in
 * the integration module; the script only carries the id, version and input/output mapping.
 */
export const DataSourceRefSchema = z
  .strictObject({
    id: IdentifierSchema,
    ref: z
      .string()
      .regex(
        /^tenant-datasource:[a-z][a-z0-9]*(-[a-z0-9]+)*$/,
        'Expected "tenant-datasource:<key>"',
      ),
    version: z.int().min(1),
    inputs: z.record(IdentifierSchema, ValueSchema).default({}),
    outputs: z.record(IdentifierSchema, DataSourceOutputSchema).default({}),
    policy: z
      .strictObject({
        trigger: z.enum(['manual', 'onEnter']).default('manual'),
        timeoutMs: z.int().min(100).max(30_000).default(5_000),
        cacheTtlSec: z.int().min(0).max(3_600).default(0),
      })
      .prefault({}),
  })
  .meta({ id: 'DataSourceRef' });

export type DataSourceRef = z.infer<typeof DataSourceRefSchema>;

src/schema/document.ts.source:
import { z } from 'zod';

import { ScriptIdSchema } from '../ids.js';
import { SCRIPT_SCHEMA_VERSION, SemverSchema } from '../version.js';

import { DataSourceRefSchema } from './data-source.js';
import { FlowSchema } from './flow.js';
import { ComponentTypeSchema } from './node.js';
import { PageSchema } from './page.js';
import { TestScenarioSchema } from './preview.js';
import { LocaleSchema, I18nKeySchema, ToneTokenSchema } from './primitives.js';
import { RuleSchema } from './rule.js';
import { VariableSchema } from './variable.js';

export const ChannelTypeSchema = z.enum([
  'voice',
  'chat',
  'email',
  'sms',
  'whatsapp',
  'social',
  'video',
  'callback',
]);
export type ChannelType = z.infer<typeof ChannelTypeSchema>;

export const ScriptMetaSchema = z.strictObject({
  /** Authoring name (tenant content). */
  name: z.string().trim().min(1).max(120),
  description: z.string().max(2_000).optional(),
  tags: z.array(z.string().min(1).max(40)).max(20).default([]),
  channels: z.array(ChannelTypeSchema).default([]),
  /** Platform capabilities the script needs, e.g. `transfer`, `hold` (validated against the channel at runtime). */
  capabilities: z.array(z.string().regex(/^[a-z][a-zA-Z0-9]*$/)).default([]),
});

export const ThemeOverrideSchema = z.strictObject({
  mode: z.enum(['inherit', 'light', 'dark']).default('inherit'),
  tokens: z
    .strictObject({
      density: z.enum(['compact', 'comfortable']).optional(),
      radius: z.enum(['none', 'sm', 'md', 'lg']).optional(),
      accent: ToneTokenSchema.optional(),
    })
    .default({}),
});

export const I18nSchema = z
  .strictObject({
    defaultLocale: LocaleSchema,
    /** `messages[locale][key]` — flat dictionaries, ICU MessageFormat values. */
    messages: z.record(LocaleSchema, z.record(I18nKeySchema, z.string().max(4_000))),
  })
  .meta({ id: 'ScriptI18n' });
export type ScriptI18n = z.infer<typeof I18nSchema>;

export const ComponentRegistryEntrySchema = z.strictObject({
  type: ComponentTypeSchema,
  version: SemverSchema,
  integrity: z.string().regex(/^sha(256|384|512)-[A-Za-z0-9+/]+={0,2}$/, 'Expected an SRI hash'),
});

export const ScriptDocumentSchema = z
  .strictObject({
    schemaVersion: z.literal(SCRIPT_SCHEMA_VERSION),
    id: ScriptIdSchema,
    meta: ScriptMetaSchema,
    variables: z.array(VariableSchema).default([]),
    dataSources: z.array(DataSourceRefSchema).default([]),
    pages: z.array(PageSchema).min(1),
    flow: FlowSchema,
    subflows: z.array(FlowSchema).default([]),
    rules: z.array(RuleSchema).default([]),
    theme: ThemeOverrideSchema.optional(),
    i18n: I18nSchema,
    componentRegistry: z.array(ComponentRegistryEntrySchema).default([]),
    testScenarios: z.array(TestScenarioSchema).max(20).optional(),
  })
  .meta({
    id: 'ScriptDocument',
    title: 'Verbis script document',
    description: 'Pure-data script version document (docs/SCRIPT_MODEL.md, ADR-0006, ADR-0010).',
  });

/** Parsed (defaults applied) document. */
export type ScriptDocument = z.infer<typeof ScriptDocumentSchema>;
/** Authoring shape (defaults optional). Fixtures and editors produce this. */
export type ScriptDocumentInput = z.input<typeof ScriptDocumentSchema>;

src/schema/flow.ts.source:
import { z } from 'zod';

import { IdentifierSchema, NodeIdSchema } from '../ids.js';

import { OutcomeCodeSchema } from './actions.js';
import { ConditionSchema, I18nKeySchema, ValueSchema } from './primitives.js';

const flowNodeBase = {
  id: NodeIdSchema,
  labelKey: I18nKeySchema.optional(),
  /** Designer canvas position; ignored at runtime and excluded from checksums. */
  position: z.strictObject({ x: z.number(), y: z.number() }).optional(),
};

export const PageFlowNodeSchema = z.strictObject({
  ...flowNodeBase,
  type: z.literal('page'),
  page: NodeIdSchema,
});
export const DecisionFlowNodeSchema = z.strictObject({
  ...flowNodeBase,
  type: z.literal('decision'),
});
export const DataSourceFlowNodeSchema = z.strictObject({
  ...flowNodeBase,
  type: z.literal('dataSource'),
  dataSource: IdentifierSchema,
});
export const SetVariableFlowNodeSchema = z.strictObject({
  ...flowNodeBase,
  type: z.literal('setVariable'),
  variable: IdentifierSchema,
  value: ValueSchema,
});
export const SubflowFlowNodeSchema = z.strictObject({
  ...flowNodeBase,
  type: z.literal('subflow'),
  flow: NodeIdSchema,
});
export const EndFlowNodeSchema = z.strictObject({
  ...flowNodeBase,
  type: z.literal('end'),
  outcome: OutcomeCodeSchema.optional(),
  disposition: OutcomeCodeSchema.optional(),
});

export const StartFlowNodeSchema = z.strictObject({ ...flowNodeBase, type: z.literal('start') });
export const TransferFlowNodeSchema = z.strictObject({
  ...flowNodeBase,
  type: z.literal('transfer'),
  target: z.string().min(1).max(128),
  reasonKey: I18nKeySchema.optional(),
});

export const FlowNodeSchema = z
  .discriminatedUnion('type', [
    StartFlowNodeSchema,
    TransferFlowNodeSchema,
    PageFlowNodeSchema,
    DecisionFlowNodeSchema,
    DataSourceFlowNodeSchema,
    SetVariableFlowNodeSchema,
    SubflowFlowNodeSchema,
    EndFlowNodeSchema,
  ])
  .meta({ id: 'FlowNode' });
export type FlowNode = z.infer<typeof FlowNodeSchema>;
export type FlowNodeType = FlowNode['type'];

export const FlowEdgeSchema = z
  .strictObject({
    id: NodeIdSchema,
    from: NodeIdSchema,
    to: NodeIdSchema,
    /** Edge is taken when the condition holds; edges are evaluated in declaration order. */
    when: ConditionSchema.optional(),
    /** Outcome port of a `dataSource` node. */
    port: z.enum(['success', 'error']).optional(),
    /** Fallback edge when no conditional edge matches. */
    default: z.boolean().optional(),
    /** Marks an intentional loop edge; the runtime stops after this many traversals. */
    maxIterations: z.int().min(1).max(1_000).optional(),
  })
  .meta({ id: 'FlowEdge' });
export type FlowEdge = z.infer<typeof FlowEdgeSchema>;

export const FlowSchema = z
  .strictObject({
    id: NodeIdSchema,
    name: z.string().trim().min(1).max(120).optional(),
    start: NodeIdSchema,
    nodes: z.array(FlowNodeSchema).min(1),
    edges: z.array(FlowEdgeSchema).default([]),
    designer: z
      .strictObject({
        groups: z
          .array(
            z.strictObject({
              id: NodeIdSchema,
              label: z.string().max(120),
              nodes: z.array(NodeIdSchema),
            }),
          )
          .default([]),
        notes: z
          .array(
            z.strictObject({
              id: NodeIdSchema,
              text: z.string().max(2000),
              position: z.strictObject({ x: z.number(), y: z.number() }),
            }),
          )
          .default([]),
      })
      .optional(),
    limits: z.strictObject({ maxSteps: z.int().min(1).max(10_000).default(200) }).prefault({}),
  })
  .meta({ id: 'Flow' });
export type Flow = z.infer<typeof FlowSchema>;
export type FlowInput = z.input<typeof FlowSchema>;

