import { z } from 'zod';

import { NodeIdSchema } from '../ids.js';

import { ActionSchema } from './actions.js';
import { NodeSchema } from './node.js';
import { I18nKeySchema } from './primitives.js';

export const TimerSchema = z
  .strictObject({
    id: NodeIdSchema,
    durationMs: z.int().min(1_000).max(86_400_000),
    repeat: z.boolean().default(false),
    autoStart: z.boolean().default(false),
    onElapsed: z.array(ActionSchema).min(1),
  })
  .meta({ id: 'Timer' });
export type Timer = z.infer<typeof TimerSchema>;

export const PageSchema = z
  .strictObject({
    id: NodeIdSchema,
    /** Authoring label shown in the designer (tenant content, not platform UI text). */
    name: z.string().trim().min(1).max(120),
    /** Runtime title shown to the agent. */
    titleKey: I18nKeySchema.optional(),
    layout: NodeSchema,
    onEnter: z.array(ActionSchema).default([]),
    onLeave: z.array(ActionSchema).default([]),
    /** The agent may not leave the session until this page has been visited and validated. */
    mandatory: z.boolean().default(false),
    timers: z.array(TimerSchema).default([]),
  })
  .meta({ id: 'Page' });

export type Page = z.infer<typeof PageSchema>;
export type PageInput = z.input<typeof PageSchema>;

src/schema/primitives.ts.source:
import { z } from 'zod';

import { NodeIdSchema } from '../ids.js';

/** Mirrors `DEFAULT_EXPRESSION_LIMITS.maxSourceLength` in `@verbis/expr` (ADR-0007). */
export const MAX_EXPRESSION_LENGTH = 2_000;

/** Arbitrary JSON (no functions, no undefined). */
export const JsonValueSchema = z.json().meta({ id: 'JsonValue' });
export type JsonValue = z.infer<typeof JsonValueSchema>;

/** Source text of a sandboxed expression (ADR-0007). Never evaluated by this package. */
export const ExpressionSchema = z.string().trim().min(1).max(MAX_EXPRESSION_LENGTH);

export const ExpressionRefSchema = z.strictObject({ $expr: ExpressionSchema }).meta({
  id: 'ExpressionRef',
  description: 'A value computed by the safe expression engine.',
});
export type ExpressionRef = z.infer<typeof ExpressionRefSchema>;

/** A literal JSON value or an expression. */
export const ValueSchema = z.union([ExpressionRefSchema, JsonValueSchema]).meta({ id: 'Value' });
export type Value = z.infer<typeof ValueSchema>;

export const RuleRefSchema = z.strictObject({ $rule: NodeIdSchema }).meta({ id: 'RuleRef' });

/** Boolean condition: an expression or a reference to a named rule. */
export const ConditionSchema = z
  .union([ExpressionRefSchema, RuleRefSchema])
  .meta({ id: 'Condition' });
export type Condition = z.infer<typeof ConditionSchema>;

/** Translation key, e.g. `offer.title`. Display text is never stored inline (CLAUDE.md rule 5). */
export const I18nKeySchema = z
  .string()
  .min(1)
  .max(128)
  .regex(
    /^[a-zA-Z][a-zA-Z0-9]*(\.[a-zA-Z0-9]+)*$/,
    'Expected a dotted i18n key (e.g. "offer.title")',
  );
export type I18nKey = z.infer<typeof I18nKeySchema>;

/** BCP 47 subset: `tr`, `en`, `en-GB`. */
export const LocaleSchema = z
  .string()
  .regex(/^[a-z]{2}(-[A-Z]{2})?$/, 'Expected a locale like "tr" or "en-GB"');
export type Locale = z.infer<typeof LocaleSchema>;

/** Design-token scales (CLAUDE.md §9: no ad-hoc colors or sizes). */
export const SpaceTokenSchema = z.enum(['none', 'xs', 'sm', 'md', 'lg', 'xl', '2xl']);
export const ToneTokenSchema = z.enum([
  'neutral',
  'primary',
  'success',
  'warning',
  'danger',
  'info',
]);
export type ToneToken = z.infer<typeof ToneTokenSchema>;

src/schema/rule.ts.source:
import { z } from 'zod';

import { NodeIdSchema } from '../ids.js';

import { ActionSchema } from './actions.js';
import {
  ExpressionRefSchema,
  JsonValueSchema,
  type ExpressionRef,
  type JsonValue,
} from './primitives.js';

export const RULE_OPERATORS = [
  'eq',
  'neq',
  'gt',
  'gte',
  'lt',
  'lte',
  'in',
  'notIn',
  'contains',
  'startsWith',
  'matches',
  'exists',
  'between',
  'before',
  'after',
] as const;
export const RuleOperatorSchema = z.enum(RULE_OPERATORS);
export type RuleOperator = z.infer<typeof RuleOperatorSchema>;

/** Fact path read by a rule leaf, e.g. `vars.segment`, `ds.customerLookup.balance`. */
export const FactPathSchema = z
  .string()
  .max(256)
  .regex(
    /^(vars|ds|interaction|agent|campaign|const)(\.[A-Za-z0-9_]+)+$/,
    'Expected a fact path like "vars.segment"',
  );

export interface PredicateLeaf {
  fact: string;
  op: RuleOperator;
  value?: JsonValue | undefined;
}
export type Predicate =
  { all: Predicate[] } | { any: Predicate[] } | { not: Predicate } | PredicateLeaf | ExpressionRef;

export const PredicateLeafSchema = z.strictObject({
  fact: FactPathSchema,
  op: RuleOperatorSchema,
  value: JsonValueSchema.optional(),
});

/** JSON predicate tree (SCRIPT_MODEL §6); the same format the rule builder edits. */
export const PredicateSchema: z.ZodType<Predicate> = z
  .lazy(() =>
    z.union([
      z.strictObject({ all: z.array(PredicateSchema).min(1) }),
      z.strictObject({ any: z.array(PredicateSchema).min(1) }),
      z.strictObject({ not: PredicateSchema }),
      PredicateLeafSchema,
      ExpressionRefSchema,
    ]),
  )
  .meta({ id: 'Predicate' });

export const RuleSchema = z
  .strictObject({
    id: NodeIdSchema,
    description: z.string().max(500).optional(),
    when: PredicateSchema,
    then: z.array(ActionSchema).default([]),
    else: z.array(ActionSchema).optional(),
  })
  .meta({ id: 'Rule' });
export type Rule = z.infer<typeof RuleSchema>;

