import { enablePatches, produceWithPatches } from 'immer';
import { describe, expect, it } from 'vitest';

import { applyJsonPatch, JsonPatchError, toJsonPatch } from './json-patch.js';

describe('toJsonPatch', () => {
  it('converts immer patches to RFC 6902 with escaped pointers', () => {
    enablePatches();
    const [, patches] = produceWithPatches(
      { 'a/b': 1, list: [1, 2], gone: true } as Record<string, unknown>,
      (draft) => {
        draft['a/b'] = 2;
        (draft['list'] as number[]).push(3);
        delete draft['gone'];
      },
    );
    expect(toJsonPatch(patches)).toEqual(
      expect.arrayContaining([
        { op: 'replace', path: '/a~1b', value: 2 },
        { op: 'add', path: '/list/2', value: 3 },
        { op: 'remove', path: '/gone' },
      ]),
    );
  });
});

describe('applyJsonPatch', () => {
  const base = { a: { b: [1, 2, 3] }, c: 'x' };

  it('applies add / replace / remove on objects and arrays without mutating', () => {
    const next = applyJsonPatch(base, [
      { op: 'add', path: '/a/b/1', value: 9 },
      { op: 'add', path: '/a/b/-', value: 4 },
      { op: 'remove', path: '/a/b/0' },
      { op: 'replace', path: '/a/b/0', value: 8 },
      { op: 'add', path: '/d', value: { e: 1 } },
      { op: 'replace', path: '/c', value: 'y' },
      { op: 'remove', path: '/d/e' },
    ]);
    expect(next).toEqual({ a: { b: [8, 2, 3, 4] }, c: 'y', d: {} });
    expect(base).toEqual({ a: { b: [1, 2, 3] }, c: 'x' });
  });

  it('copies inserted values', () => {
    const value = { deep: [1] };
    const next = applyJsonPatch({ list: [] as unknown[] }, [{ op: 'add', path: '/list/0', value }]);
    value.deep.push(2);
    expect(next.list[0]).toEqual({ deep: [1] });
  });

  it.each([
    ['root replace', { op: 'replace', path: '', value: 1 }],
    ['missing parent', { op: 'add', path: '/x/y', value: 1 }],
    ['primitive parent', { op: 'add', path: '/c/y', value: 1 }],
    ['traversal through primitive', { op: 'add', path: '/c/y/z', value: 1 }],
    ['missing key', { op: 'remove', path: '/zzz' }],
    ['bad index', { op: 'replace', path: '/a/b/x', value: 1 }],
    ['leading zero index', { op: 'remove', path: '/a/b/01' }],
    ['index past end', { op: 'replace', path: '/a/b/3', value: 1 }],
    ['add past end', { op: 'add', path: '/a/b/5', value: 1 }],
    ['dash on remove', { op: 'remove', path: '/a/b/-' }],
    ['dash while traversing', { op: 'add', path: '/a/b/-/x', value: 1 }],
  ] as const)('rejects %s', (_label, operation) => {
    expect(() => applyJsonPatch(base, [operation])).toThrow(JsonPatchError);
  });

  it('exposes the failing operation', () => {
    const operation = { op: 'remove', path: '/nope' } as const;
    try {
      applyJsonPatch(base, [operation]);
    } catch (error) {
      expect(error).toMatchObject({ name: 'JsonPatchError', operation });
    }
  });
});

src/helpers.spec.ts.source:
import { describe, expect, it } from 'vitest';

import { BUILTIN_COMPONENT_TYPES, CORE_PRIMITIVE_TYPES } from './components.js';
import { IdentifierSchema, ScriptIdSchema } from './ids.js';
import { cloneJson, utf8ByteLength } from './json.js';
import { fromPointer, toPointer } from './pointer.js';

describe('JSON Pointer', () => {
  it('escapes and round-trips (RFC 6901)', () => {
    const segments = ['pages', 0, 'a/b', 'c~d', ''];
    const pointer = toPointer(segments);
    expect(pointer).toBe('/pages/0/a~1b/c~0d/');
    expect(fromPointer(pointer)).toEqual(['pages', '0', 'a/b', 'c~d', '']);
    expect(toPointer([])).toBe('');
    expect(fromPointer('')).toEqual([]);
  });

  it('rejects pointers without a leading slash', () => {
    expect(() => fromPointer('pages/0')).toThrow('Invalid JSON Pointer');
  });
});

describe('json helpers', () => {
  it('deep-clones JSON', () => {
    const value = { a: [1, { b: 'c' }] };
    const copy = cloneJson(value);
    expect(copy).toEqual(value);
    expect(copy.a).not.toBe(value.a);
  });

  it('counts UTF-8 bytes', () => {
    expect(utf8ByteLength('abc')).toBe(3);
    expect(utf8ByteLength('ş')).toBe(2);
    expect(utf8ByteLength('€')).toBe(3);
    expect(utf8ByteLength('😀')).toBe(4);
  });
});

describe('ids', () => {
  it('validates identifiers and UUIDv7 script ids', () => {
    expect(IdentifierSchema.safeParse('customerName').success).toBe(true);
    expect(IdentifierSchema.safeParse('customer-name').success).toBe(false);
    expect(ScriptIdSchema.safeParse('01928f3a-0000-7000-8000-000000000001').success).toBe(true);
    expect(ScriptIdSchema.safeParse('7c9e6679-7425-40de-944b-e07fc1f90ae7').success).toBe(false);
  });
});

describe('components', () => {
  it('includes the core primitives', () => {
    expect(BUILTIN_COMPONENT_TYPES).toEqual(expect.arrayContaining([...CORE_PRIMITIVE_TYPES]));
  });
});

src/validation/references.spec.ts.source:
import { describe, expect, it } from 'vitest';

import { scanExpression, scanFactPath } from './references.js';

describe('scanExpression', () => {
  it('finds variable and data source references', () => {
    expect(scanExpression('vars.a + vars.b * 2 > ds.lookup.score && ds.other')).toEqual({
      variables: ['a', 'b'],
      dataSources: [{ id: 'lookup', field: 'score' }, { id: 'other' }],
    });
  });

  it('ignores references inside string literals (with escapes)', () => {
    expect(scanExpression(`"vars.nope" + 'it\\'s vars.nope2' + vars.yes`).variables).toEqual([
      'yes',
    ]);
  });

  it('ignores member access on other roots and number literals', () => {
    expect(scanExpression('agent.vars.x + 1.5e3 + obj.ds.y + interaction.ani').variables).toEqual(
      [],
    );
    expect(scanExpression('1.vars').variables).toEqual([]);
  });

  it('handles bare roots, calls and object literals', () => {
    expect(scanExpression('vars').variables).toEqual([]);
    expect(scanExpression('min(vars.limit, vars.max)').variables).toEqual(['limit', 'max']);
    expect(scanExpression('{ name: vars.customerName }').variables).toEqual(['customerName']);
    expect(scanExpression('vars. x').variables).toEqual([]);
  });

  it('deduplicates', () => {
    expect(scanExpression('vars.a + vars.a + ds.x.y + ds.x.y')).toEqual({
      variables: ['a'],
      dataSources: [{ id: 'x', field: 'y' }],
    });
  });

  it('scans fact paths', () => {
    expect(scanFactPath('vars.segment').variables).toEqual(['segment']);
    expect(scanFactPath('ds.lookup.balance').dataSources).toEqual([
      { id: 'lookup', field: 'balance' },
    ]);
  });
});

