import { describe, expect, it } from 'vitest';

import { en, flattenKeys, tr } from '@verbis/i18n';

import { createIssue, hasErrors, messageKeyFor, VALIDATION_CODES } from './issues.js';

describe('messageKeyFor', () => {
  it('derives camelCase keys', () => {
    expect(messageKeyFor('FLOW_CYCLE')).toBe('script.validation.flowCycle');
    expect(messageKeyFor('I18N_KEY_MISSING')).toBe('script.validation.i18nKeyMissing');
  });

  it('every code has tr and en messages (CLAUDE.md rule 5)', () => {
    const trKeys = new Set(flattenKeys(tr));
    const enKeys = new Set(flattenKeys(en));
    for (const code of VALIDATION_CODES) {
      expect(trKeys, code).toContain(messageKeyFor(code));
      expect(enKeys, code).toContain(messageKeyFor(code));
    }
  });

  it('codes are unique', () => {
    expect(new Set(VALIDATION_CODES).size).toBe(VALIDATION_CODES.length);
  });
});

describe('createIssue / hasErrors', () => {
  it('omits params when not given', () => {
    expect(createIssue('warning', 'FLOW_DEAD_END', '/flow')).toEqual({
      severity: 'warning',
      path: '/flow',
      code: 'FLOW_DEAD_END',
      messageKey: 'script.validation.flowDeadEnd',
    });
    expect(createIssue('error', 'DUPLICATE_ID', '', { id: 'a' }).params).toEqual({ id: 'a' });
  });

  it('detects errors', () => {
    expect(hasErrors([createIssue('warning', 'FLOW_DEAD_END', '')])).toBe(false);
    expect(
      hasErrors([createIssue('info', 'FLOW_DEAD_END', ''), createIssue('error', 'FLOW_CYCLE', '')]),
    ).toBe(true);
  });
});

src/tree/patch-boundaries.spec.ts.source:
import { describe, expect, it } from 'vitest';

import { applyJsonPatch, JsonPatchError } from './json-patch.js';

describe('atomic patch and array boundary regressions', () => {
  it.each(['-1', '01', '1.0', '2', '-'])('rejects invalid replacement index %s', (index) => {
    const original = { values: ['first', 'second'] };
    expect(() =>
      applyJsonPatch(original, [{ op: 'replace', path: `/values/${index}`, value: 'changed' }]),
    ).toThrow(JsonPatchError);
    expect(original).toEqual({ values: ['first', 'second'] });
  });
  it('permits append at length and rejects removal at length', () => {
    const original = { values: ['first'] };
    expect(applyJsonPatch(original, [{ op: 'add', path: '/values/1', value: 'second' }])).toEqual({
      values: ['first', 'second'],
    });
    expect(() => applyJsonPatch(original, [{ op: 'remove', path: '/values/1' }])).toThrow(
      JsonPatchError,
    );
  });
  it('rolls back earlier operations when a later operation is invalid', () => {
    const original = { name: 'before', values: [1] };
    expect(() =>
      applyJsonPatch(original, [
        { op: 'replace', path: '/name', value: 'after' },
        { op: 'remove', path: '/values/2' },
      ]),
    ).toThrow(JsonPatchError);
    expect(original).toEqual({ name: 'before', values: [1] });
  });
  it('copies inserted values and preserves unrelated structural sharing', () => {
    const original = { values: [] as { value: number }[], stable: { key: 'unchanged' } };
    const inserted = { value: 1 };
    const updated = applyJsonPatch(original, [{ op: 'add', path: '/values/-', value: inserted }]);
    inserted.value = 2;
    expect(updated.values).toEqual([{ value: 1 }]);
    expect(updated.stable).toBe(original.stable);
    expect(original.values).toEqual([]);
  });
});

